package expenses

import "testing"

var testExpensesRecords = []Record{
	{
		Day:      1,
		Amount:   5.15,
		Category: "groceries",
	},
	{
		Day:      1,
		Amount:   3.45,
		Category: "groceries",
	},
	{
		Day:      13,
		Amount:   55.67,
		Category: "utility-bills",
	},
	{
		Day:      15,
		Amount:   11,
		Category: "groceries",
	},
	{
		Day:      18,
